function applyCatalogQuery(){const params=new URLSearchParams(location.search),cat=params.get('category'),btu=params.get('btu'),q=params.get('q');if(q&&document.querySelector('#catalog-search'))document.querySelector('#catalog-search').value=q;if(cat){const radio=[...document.querySelectorAll('[name=category]')].find(x=>x.value===cat||cat.includes(x.value));if(radio)radio.checked=true}if(btu){const chip=[...document.querySelectorAll('.chip')].find(x=>x.dataset.btu&&btu.includes(x.dataset.btu.replace('.','')));if(chip){document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));chip.classList.add('active')}}renderCatalog()}
