function renderRegionPage(){const root=document.querySelector('[data-region-page]');if(!root)return;const slug=new URLSearchParams(location.search).get('city')||'aydin';/* The URL value is only ever used as a lookup key: an unknown city renders the generic page and is never echoed into the markup. */const region=regions.find(x=>x[0]===slug),name=region?.[1]||'Ege Bölgesi';root.innerHTML=`<div class="eyebrow">Ege Teknik hizmet bölgesi</div><h1>${name} Klima Satış, Montaj ve Servis</h1><p class="lead">Kuşadası merkezli Ege Teknik; ${name} genelinde GREE klima satışı, keşif, montaj, bakım, onarım ve yedek parça taleplerini planlı servis organizasyonuyla karşılar.</p><div class="service-grid"><article><b>Klima satışı</b><p>İhtiyaca uygun BTU ve seri seçimi, online sipariş veya teklif.</p></article><article><b>Keşif ve montaj</b><p>Mekân koşulları, borulama ve dış ünite konumunun değerlendirilmesi.</p></article><article><b>Bakım ve onarım</b><p>Periyodik bakım, arıza kontrolü ve parça temini.</p></article></div><div class="region-cta"><div><h2>${name} için servis veya keşif isteyin</h2><p>Adresinizi ve ihtiyacınızı iletin; uygun hizmet planı için sizi arayalım.</p></div><a class="primary" href="contact.html${region?`?city=${region[0]}`:''}">Talep oluştur</a></div>`;document.title=name+' Klima Servisi ve Satış | Ege Teknik'}
